1	package server
2	
3	import (
4		"encoding/json"
5		"fmt"
6		"math/big"
7		"net/http"
8		"sort"
9	)
10	
11	// Error code reported when the plan request envelope or the prior state
12	// document is structurally invalid.
13	const codeInvalidPlanRequest = "invalid_plan_request"
14	
15	// planSnapshot is the normalized view of one resource at one side of a
16	// change: before for the prior state, after for the configuration.
17	type planSnapshot struct {
18		Type       string         `json:"type"`
19		Properties map[string]any `json:"properties"`
20		DependsOn  []string       `json:"dependsOn"`
21	}
22	
23	// planChange is one planned action. Create carries only After, delete only
24	// Before, update carries both.
25	type planChange struct {
26		Address string        `json:"address"`
27		Action  string        `json:"action"`
28		Before  *planSnapshot `json:"before,omitempty"`
29		After   *planSnapshot `json:"after,omitempty"`
30	}
31	
32	type planSummary struct {
33		Create int `json:"create"`
34		Update int `json:"update"`
35		Delete int `json:"delete"`
36		Noop   int `json:"noop"`
37	}
38	
39	type planResponse struct {
40		Valid   bool              `json:"valid"`
41		Errors  []validationError `json:"errors"`
42		Changes []planChange      `json:"changes"`
43		Summary planSummary       `json:"summary"`
44	}
45	
46	// planResource is the plan-relevant view of one resource, extracted from an
47	// already-validated configuration or prior state document.
48	type planResource struct {
49		address    string
50		typ        string
51		properties map[string]any
52		dependsOn  []string
53	}
54	
55	// handlePlanConfiguration computes the diff between a desired configuration
56	// and a prior state. It only computes the plan; nothing is applied or
57	// persisted.
58	func handlePlan(w http.ResponseWriter, r *http.Request) {
59		w.Header().Set("Content-Type", "application/json; charset=utf-8")
60		if r.Method != http.MethodPost {
61			w.Header().Set("Allow", http.MethodPost)
62			w.WriteHeader(http.StatusMethodNotAllowed)
63			_ = json.NewEncoder(w).Encode(map[string]any{
64				"error": map[string]string{"code": "method_not_allowed"},
65			})
66			return
67		}
68	
69		doc, ok := decodeConfigurationBody(w, r)
70		if !ok {
71			return
72		}
73	
74		configRaw, stateRaw, ok := checkPlanEnvelope(w, doc)
75		if !ok {
76			return
77		}
78	
79		// Configuration and prior state are validated independently; their
80		// findings are merged and sorted together. Configuration findings keep
81		// their codes and gain a /configuration path prefix.
82		var errs []validationError
83		var configResources []planResource
84		var configOrder []string
85		if baseErrs := validateConfiguration(configRaw); len(baseErrs) != 0 {
86			errs = appendPrefixedErrors(errs, baseErrs, "/configuration")
87		} else if order, depErrs := orderConfiguration(configRaw); len(depErrs) != 0 {
88			errs = appendPrefixedErrors(errs, depErrs, "/configuration")
89		} else {
90			configResources = configurationResources(configRaw)
91			configOrder = order
92		}
93	
94		stateResources, stateOrder, stateErrs := checkPriorState(stateRaw)
95		errs = append(errs, stateErrs...)
96	
97		if len(errs) != 0 {
98			sortValidationErrors(errs)
99			writeValidation(w, http.StatusUnprocessableEntity, errs)
100			return
101		}
102	
103		changes, summary := computePlan(configResources, configOrder, stateResources, stateOrder)
104		w.WriteHeader(http.StatusOK)
105		_ = json.NewEncoder(w).Encode(planResponse{
106			Valid:   true,
107			Errors:  []validationError{},
108			Changes: changes,
109			Summary: summary,
110		})
111	}
112	
113	// checkPlanEnvelope validates the request envelope: a JSON object holding
114	// exactly the configuration and priorState fields. On failure it writes the
115	// 422 response and returns ok=false.
116	func checkPlanEnvelope(w http.ResponseWriter, doc any) (configuration, priorState any, ok bool) {
117		var errs []validationError
118		add := func(code, message, path string) {
119			errs = append(errs, validationError{Code: code, Message: message, Path: path})
120		}
121	
122		root, isObject := doc.(map[string]any)
123		if !isObject {
124			add(codeInvalidPlanRequest, "request body must be a JSON object", "")
125		} else {
126			for key := range root {
127				if key != "configuration" && key != "priorState" {
128					add(codeInvalidPlanRequest, fmt.Sprintf("unknown field %q", key), "/"+pointerEscape(key))
129				}
130			}
131			var hasConfig, hasState bool
132			configuration, hasConfig = root["configuration"]
133			priorState, hasState = root["priorState"]
134			if !hasConfig {
135				add(codeInvalidPlanRequest, `missing required field "configuration"`, "")
136			}
137			if !hasState {
138				add(codeInvalidPlanRequest, `missing required field "priorState"`, "")
139			}
140		}
141	
142		if len(errs) != 0 {
143			sortValidationErrors(errs)
144			writeValidation(w, http.StatusUnprocessableEntity, errs)
145			return nil, nil, false
146		}
147		return configuration, priorState, true
148	}
149	
150	// appendPrefixedErrors appends errs to dst with every path rooted at prefix,
151	// so findings from an embedded document point into the request envelope.
152	func appendPrefixedErrors(dst []validationError, errs []validationError, prefix string) []validationError {
153		for _, e := range errs {
154			e.Path = prefix + e.Path
155			dst = append(dst, e)
156		}
157		return dst
158	}
159	
160	// configurationResources extracts the plan-relevant view of an
161	// already-validated configuration document.
162	func configurationResources(doc any) []planResource {
163		root := doc.(map[string]any)
164		entries := root["resources"].([]any)
165		resources := make([]planResource, 0, len(entries))
166		for _, entry := range entries {
167			obj := entry.(map[string]any)
168			var deps []string
169			if raw, ok := obj["dependsOn"].([]any); ok {
170				for _, el := range raw {
171					deps = append(deps, el.(string))
172				}
173			}
174			resources = append(resources, planResource{
175				address:    obj["address"].(string),
176				typ:        obj["type"].(string),
177				properties: obj["properties"].(map[string]any),
178				dependsOn:  deps,
179			})
180		}
181		return resources
182	}
183	
184	// checkPriorState validates the priorState document: an object with a
185	// resources array whose entries have a non-empty unique address, a non-empty
186	// type, a properties object, and an optional dependsOn. State types are not
187	// checked against the configuration's resource types. Shape problems are
188	// reported as invalid_plan_request and suppress dependency interpretation;
189	// dependency problems reuse the configuration dependency codes.
190	func checkPriorState(raw any) ([]planResource, []string, []validationError) {
191		const base = "/priorState"
192		var errs []validationError
193		add := func(code, message, path string) {
194			errs = append(errs, validationError{Code: code, Message: message, Path: path})
195		}
196	
197		obj, ok := raw.(map[string]any)
198		if !ok {
199			add(codeInvalidPlanRequest, `"priorState" must be an object`, base)
200			return nil, nil, errs
201		}
202		resourcesRaw, hasResources := obj["resources"]
203		if !hasResources {
204			add(codeInvalidPlanRequest, `missing required field "resources"`, base)
205			return nil, nil, errs
206		}
207		entries, ok := resourcesRaw.([]any)
208		if !ok {
209			add(codeInvalidPlanRequest, `"resources" must be an array`, base+"/resources")
210			return nil, nil, errs
211		}
212	
213		resources := make([]planResource, len(entries))
214		seenAddresses := map[string]bool{}
215		for i, entry := range entries {
216			entryPath := fmt.Sprintf("%s/resources/%d", base, i)
217			entryObj, ok := entry.(map[string]any)
218			if !ok {
219				add(codeInvalidPlanRequest, "state resource entry must be an object", entryPath)
220				continue
221			}
222			address, addressOK := planStringField(entryObj, "address", entryPath, add)
223			if addressOK {
224				if seenAddresses[address] {
225					add(codeDuplicateIdentifier, fmt.Sprintf("duplicate resource address %q", address), entryPath+"/address")
226					addressOK = false
227				} else {
228					seenAddresses[address] = true
229				}
230			}
231			typ, typeOK := planStringField(entryObj, "type", entryPath, add)
232			propsRaw, hasProps := entryObj["properties"]
233			props, propsOK := propsRaw.(map[string]any)
234			switch {
235			case !hasProps:
236				add(codeInvalidPlanRequest, `missing required field "properties"`, entryPath)
237			case !propsOK:
238				add(codeInvalidPlanRequest, `"properties" must be an object`, entryPath+"/properties")
239			}
240			if !addressOK || !typeOK || !hasProps || !propsOK {
241				continue
242			}
243			resources[i] = planResource{address: address, typ: typ, properties: props}
244		}
245		if len(errs) != 0 {
246			return nil, nil, errs
247		}
248	
249		addresses := make([]string, len(entries))
250		for i, resource := range resources {
251			addresses[i] = resource.address
252		}
253		dependsOn, order, depErrs := resolveDependencies(entries, addresses, base+"/resources")
254		if len(depErrs) != 0 {
255			return nil, nil, depErrs
256		}
257		for i := range resources {
258			resources[i].dependsOn = dependsOn[i]
259		}
260		return resources, order, nil
261	}
262	
263	// planStringField extracts a required non-empty string field of a prior
264	// state entry, reporting invalid_plan_request otherwise.
265	func planStringField(obj map[string]any, field, path string, add func(code, message, path string)) (string, bool) {
266		raw, ok := obj[field]
267		if !ok {
268			add(codeInvalidPlanRequest, fmt.Sprintf("missing required field %q", field), path)
269			return "", false
270		}
271		s, ok := raw.(string)
272		if !ok {
273			add(codeInvalidPlanRequest, fmt.Sprintf("%q must be a string", field), path+"/"+field)
274			return "", false
275		}
276		if s == "" {
277			add(codeInvalidPlanRequest, fmt.Sprintf("%q must not be empty", field), path+"/"+field)
278			return "", false
279		}
280		return s, true
281	}
282	
283	// computePlan aligns desired and prior resources by address. Deletes are
284	// listed in the reverse of the prior state's topological order; creates and
285	// updates follow the configuration's deterministic topological order.
286	// Resources equal on both sides are counted as noop and produce no change.
287	func computePlan(configResources []planResource, configOrder []string, stateResources []planResource, stateOrder []string) ([]planChange, planSummary) {
288		configByAddress := make(map[string]planResource, len(configResources))
289		for _, resource := range configResources {
290			configByAddress[resource.address] = resource
291		}
292		stateByAddress := make(map[string]planResource, len(stateResources))
293		for _, resource := range stateResources {
294			stateByAddress[resource.address] = resource
295		}
296	
297		actions := make(map[string]string, len(configResources)+len(stateResources))
298		var summary planSummary
299		for _, resource := range configResources {
300			prior, existed := stateByAddress[resource.address]
301			switch {
302			case !existed:
303				actions[resource.address] = "create"
304				summary.Create++
305			case resourceEqual(resource, prior):
306				summary.Noop++
307			default:
308				actions[resource.address] = "update"
309				summary.Update++
310			}
311		}
312		for _, resource := range stateResources {
313			if _, desired := configByAddress[resource.address]; !desired {
314				actions[resource.address] = "delete"
315				summary.Delete++
316			}
317		}
318	
319		changes := make([]planChange, 0, len(actions))
320		for i := len(stateOrder) - 1; i >= 0; i-- {
321			address := stateOrder[i]
322			if actions[address] != "delete" {
323				continue
324			}
325			before := snapshotOf(stateByAddress[address])
326			changes = append(changes, planChange{Address: address, Action: "delete", Before: &before})
327		}
328		for _, address := range configOrder {
329			action := actions[address]
330			if action != "create" && action != "update" {
331				continue
332			}
333			after := snapshotOf(configByAddress[address])
334			change := planChange{Address: address, Action: action, After: &after}
335			if action == "update" {
336				before := snapshotOf(stateByAddress[address])
337				change.Before = &before
338			}
339			changes = append(changes, change)
340		}
341		return changes, summary
342	}
343	
344	// snapshotOf renders a resource as a change snapshot with its dependencies
345	// normalized to ascending order.
346	func snapshotOf(resource planResource) planSnapshot {
347		deps := make([]string, len(resource.dependsOn))
348		copy(deps, resource.dependsOn)
349		sort.Strings(deps)
350		return planSnapshot{
351			Type:       resource.typ,
352			Properties: resource.properties,
353			DependsOn:  deps,
354		}
355	}
356	
357	// resourceEqual reports whether a desired and a prior resource are
358	// equivalent: same type, deeply equal properties, and equal dependency sets.
359	func resourceEqual(desired, prior planResource) bool {
360		if desired.typ != prior.typ {
361			return false
362		}
363		if !jsonValueEqual(desired.properties, prior.properties) {
364			return false
365		}
366		return stringSetEqual(desired.dependsOn, prior.dependsOn)
367	}
368	
369	// jsonValueEqual compares two decoded JSON values. Object key order is
370	// ignored, numbers compare by numeric value, and arrays are ordered.
371	func jsonValueEqual(a, b any) bool {
372		switch av := a.(type) {
373		case json.Number:
374			bv, ok := b.(json.Number)
375			return ok && jsonNumberEqual(av, bv)
376		case map[string]any:
377			bv, ok := b.(map[string]any)
378			if !ok || len(av) != len(bv) {
379				return false
380			}
381			for key, value := range av {
382				other, present := bv[key]
383				if !present || !jsonValueEqual(value, other) {
384					return false
385				}
386			}
387			return true
388		case []any:
389			bv, ok := b.([]any)
390			if !ok || len(av) != len(bv) {
391				return false
392			}
393			for i := range av {
394				if !jsonValueEqual(av[i], bv[i]) {
395					return false
396				}
397			}
398			return true
399		default:
400			return a == b
401		}
402	}
403	
404	// jsonNumberEqual compares two JSON number literals by numeric value, so
405	// 1, 1.0, and 1e0 are all equal.
406	func jsonNumberEqual(a, b json.Number) bool {
407		ra, okA := new(big.Rat).SetString(a.String())
408		rb, okB := new(big.Rat).SetString(b.String())
409		if okA && okB {
410			return ra.Cmp(rb) == 0
411		}
412		return a.String() == b.String()
413	}
414	
415	// stringSetEqual compares two duplicate-free string lists as sets.
416	func stringSetEqual(a, b []string) bool {
417		if len(a) != len(b) {
418			return false
419		}
420		counts := make(map[string]int, len(a))
421		for _, s := range a {
422			counts[s]++
423		}
424		for _, s := range b {
425			counts[s]--
426			if counts[s] < 0 {
427				return false
428			}
429		}
430		return true
431	}
