58	// orderConfiguration interprets the dependsOn fields of a validated document.
59	// It returns every dependency problem in one pass; dependency problems take
60	// precedence over cycle detection, and cycles take precedence over ordering.
61	func orderConfiguration(doc any) ([]string, []validationError) {
62		root := doc.(map[string]any)
63		resourceEntries := root["resources"].([]any)
64	
65		addresses := make([]string, len(resourceEntries))
66		for i, entry := range resourceEntries {
67			addresses[i] = entry.(map[string]any)["address"].(string)
68		}
69	
70		_, order, errs := resolveDependencies(resourceEntries, addresses, "/resources")
71		if len(errs) != 0 {
72			return nil, errs
73		}
74		return order, nil
75	}
76	
77	// resolveDependencies interprets the dependsOn fields of resource entries
78	// whose addresses are already known to be non-empty and unique. resourcesPath
79	// is the JSON Pointer of the entries array, used as the base of error paths.
80	// It returns the per-entry dependency lists together with a deterministic
81	// topological order, or every dependency problem found; dependency problems
82	// take precedence over cycle detection, and cycles over ordering.
83	func resolveDependencies(entries []any, addresses []string, resourcesPath string) ([][]string, []string, []validationError) {
84		known := make(map[string]bool, len(addresses))
85		for _, address := range addresses {
86			known[address] = true
87		}
88	
89		var errs []validationError
90		add := func(code, message, path string) {
91			errs = append(errs, validationError{Code: code, Message: message, Path: path})
92		}
93		dependsOn := make([][]string, len(entries))
94		for i, entry := range entries {
95			obj := entry.(map[string]any)
96			raw, present := obj["dependsOn"]
97			if !present {
98				continue
99			}
100			fieldPath := fmt.Sprintf("%s/%d/dependsOn", resourcesPath, i)
101			arr, ok := raw.([]any)
102			if !ok {
103				add(codeInvalidDocument, `"dependsOn" must be an array of non-empty resource address strings`, fieldPath)
104				continue
105			}
106			seen := map[string]bool{}
107			for j, el := range arr {
108				elPath := fmt.Sprintf("%s/%d", fieldPath, j)
109				ref, isString := el.(string)
110				if !isString || ref == "" {
111					add(codeInvalidDocument, "dependency must be a non-empty resource address string", elPath)
112					continue
113				}
114				if seen[ref] {
115					add(codeDuplicateDependency, fmt.Sprintf("duplicate dependency %q", ref), elPath)
116					continue
117				}
118				seen[ref] = true
119				switch {
120				case ref == addresses[i]:
121					add(codeSelfDependency, "resource must not depend on itself", elPath)
122				case !known[ref]:
123					add(codeUnknownDependency, fmt.Sprintf("unknown dependency %q", ref), elPath)
124				default:
125					dependsOn[i] = append(dependsOn[i], ref)
126				}
127			}
128		}
129		if len(errs) != 0 {
130			return nil, nil, errs
131		}
132	
133		if cyclic := cyclicResources(addresses, dependsOn); cyclic != nil {
134			sort.Strings(cyclic)
135			errs = append(errs, validationError{
136				Code:    codeDependencyCycle,
137				Message: "dependency cycle: " + strings.Join(cyclic, ", "),
138				Path:    resourcesPath,
139			})
140			return nil, nil, errs
141		}
142	
143		return dependsOn, topologicalOrder(addresses, dependsOn), nil
144	}
145	
146	// topologicalOrder performs Kahn's algorithm, always selecting the available
147	// resource with the smallest address (Unicode code point order), so documents
148	// differing only in equivalent dependsOn permutations order identically.
149	func topologicalOrder(addresses []string, dependsOn [][]string) []string {
150		dependents := make(map[string][]string, len(addresses))
151		indegree := make(map[string]int, len(addresses))
152		for _, address := range addresses {
153			indegree[address] = 0
154		}
155		for i, deps := range dependsOn {
156			indegree[addresses[i]] = len(deps)
157			for _, dep := range deps {
158				dependents[dep] = append(dependents[dep], addresses[i])
159			}
160		}
161	
162		var ready []string
163		for _, address := range addresses {
164			if indegree[address] == 0 {
165				ready = append(ready, address)
166			}
167		}
168	
169		order := make([]string, 0, len(addresses))
170		for len(ready) > 0 {
171			sort.Strings(ready)
172			next := ready[0]
173			ready = ready[1:]
174			order = append(order, next)
175			for _, dependent := range dependents[next] {
176				indegree[dependent]--
177				if indegree[dependent] == 0 {
178					ready = append(ready, dependent)
179				}
180			}
181		}
182		return order
183	}
184	
185	// cyclicResources returns the addresses that actually lie on a dependency
186	// cycle. Resources that merely depend, directly or indirectly, on a cycle
187	// without being part of one are excluded. Self-loops cannot occur because
188	// self dependencies are rejected beforehand.
189	func cyclicResources(addresses []string, dependsOn [][]string) []string {
190		index := make(map[string]int, len(addresses))
191		for i, address := range addresses {
192			index[address] = i
193		}
194	
195		// Tarjan's strongly connected components algorithm, iteratively to
196		// avoid recursion-depth concerns on long dependency chains.
197		indices := make([]int, len(addresses))
198		lowlink := make([]int, len(addresses))
199		onStack := make([]bool, len(addresses))
200		for i := range indices {
201			indices[i] = -1
202		}
203		var stack []int
204		var nextIndex int
205		var cyclic []string
206	
207		type frame struct {
208			v    int
209			edge int
210		}
211		for root := range addresses {
212			if indices[root] != -1 {
213				continue
214			}
215			indices[root] = nextIndex
216			lowlink[root] = nextIndex
217			nextIndex++
218			stack = append(stack, root)
219			onStack[root] = true
220			work := []frame{{v: root}}
221			for len(work) > 0 {
222				top := len(work) - 1
223				v := work[top].v
224				if work[top].edge < len(dependsOn[v]) {
225					w := index[dependsOn[v][work[top].edge]]
226					work[top].edge++
227					if indices[w] == -1 {
228						indices[w] = nextIndex
229						lowlink[w] = nextIndex
230						nextIndex++
231						stack = append(stack, w)
232						onStack[w] = true
233						work = append(work, frame{v: w})
234						continue
235					}
236					if onStack[w] && indices[w] < lowlink[v] {
237						lowlink[v] = indices[w]
238					}
239					continue
240				}
241				if lowlink[v] == indices[v] {
242					var component []string
243					for {
244						w := stack[len(stack)-1]
245						stack = stack[:len(stack)-1]
246						onStack[w] = false
247						component = append(component, addresses[w])
248						if w == v {
249							break
250						}
251					}
252					// With self-loops rejected, a component of two or more
253					// nodes is exactly a cycle.
254					if len(component) > 1 {
255						cyclic = append(cyclic, component...)
256					}
257				}
258				work = work[:len(work)-1]
259				if len(work) > 0 {
260					if parent := work[len(work)-1].v; lowlink[v] < lowlink[parent] {
261						lowlink[parent] = lowlink[v]
262					}
263				}
264			}
265		}
266		return cyclic
267	}
