			[]string{"unknown_dependency@/configuration/resources/0/dependsOn/0"},
		},
		"cycle": {
			`{"resourceTypes": [{"name": "t", "schema": {"type": "object"}}], "resources": [` +
				resEntry("a", `["b"]`) + `,` + resEntry("b", `["a"]`) + `]}`,
